package com.bank.sign.service;

import java.util.logging.Logger;

// Counts +/- sign assignments reaching a target by reducing to subset-sum counting.
public class SignAssignmentService {
    private static final Logger log = Logger.getLogger(SignAssignmentService.class.getName());

    public long countWays(int[] amounts, int target) {
        int total = 0;
        for (int a : amounts) total += a;
        // Guards: need (total + target) even and |target| <= total.
        if (Math.abs(target) > total || (total + target) % 2 != 0) {
            log.info("No valid sign assignment exists");
            return 0;
        }
        int derived = (total + target) / 2;          // positive-group sum P
        long[] dp = new long[derived + 1];
        dp[0] = 1;                                    // empty positive group
        for (int num : amounts) {
            for (int t = derived; t >= num; t--) {    // high → low ⇒ each item once
                dp[t] += dp[t - num];
            }
        }
        log.info(() -> "Sign assignments reaching target = " + dp[derived]);
        return dp[derived];
    }
}
