package com.bank.sign;

import com.bank.sign.service.SignAssignmentService;
import java.util.logging.Logger;

public class SignAssignmentApplication {
    private static final Logger log = Logger.getLogger(SignAssignmentApplication.class.getName());

    public static void main(String[] args) {
        SignAssignmentService service = new SignAssignmentService();
        int[] adjustments = {1, 1, 2, 3};      // adjustment amounts (thousands)
        int target = 1;                         // required net effect
        long ways = service.countWays(adjustments, target);
        log.info("Number of sign assignments reaching net " + target + ": " + ways);
    }
}
